# CORRECT: META lambda adapts grid to autotuner's winning config
@triton.autotune(configs=[Config({'XBLOCK':128,'YBLOCK':8}), Config({'XBLOCK':64,'YBLOCK':4}), ...], key=[...])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: constexpr, XBLOCK: constexpr):
    ...

# Grid uses META to match whichever tile sizes the autotuner selects
grid = lambda META: (cdiv(xnumel, META['XBLOCK']), cdiv(ynumel, META['YBLOCK']))
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)
